-- ==============================================================================
-- MIGRASI DATABASE: SEEDING 50 SOAL KUIS EDUKASI SMP KE TABEL QUIZZES
-- Platform: SIGMA Platform (SMPN 4 Sumberjambe)
-- Jalankan skrip ini di Supabase SQL Editor (Dashboard Supabase -> SQL Editor -> New Query)
-- ==============================================================================

-- 1. Pastikan ekstensi pgcrypto aktif untuk gen_random_uuid()
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. Pastikan tabel quizzes ada (sesuai struktur tabel Supabase Anda)
CREATE TABLE IF NOT EXISTS public.quizzes (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  category text NOT NULL,
  question_text text NOT NULL,
  options text[] NOT NULL,
  correct_answer integer NOT NULL,
  explanation text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT quizzes_pkey PRIMARY KEY (id)
);

-- 3. Row Level Security (RLS) agar siswa bisa baca & admin bisa kelola
ALTER TABLE public.quizzes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read quizzes" ON public.quizzes;
CREATE POLICY "Public read quizzes"
  ON public.quizzes
  FOR SELECT
  USING (true);

DROP POLICY IF EXISTS "Allow manage quizzes" ON public.quizzes;
CREATE POLICY "Allow manage quizzes"
  ON public.quizzes
  FOR ALL
  USING (true)
  WITH CHECK (true);

-- 4. Bersihkan data kuis lama agar bersih dan tidak duplikat
TRUNCATE TABLE public.quizzes;

